test("number on settle scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-B", "3");
  await ui.setSetting(pg_uma, "perm-settle", "steward");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "7.77", "note": "tpl"})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "33.33");
  await ui.setSetting(pg_uma, "fiscal-start-month", "4");
  await ui.setSetting(pg_uma, "review-threshold", "4.00");
  await ui.setSetting(pg_uma, "review-sla", "1");
  await ui.setSetting(pg_uma, "proof-kinds", "receipt,photo");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00", "from": "2026-03-01"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "terms": "3", "tags": "a"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "tags": "c"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "3", "tags": "b, a"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "33.33"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "33.33"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "33.34", "from": "2026-03-01", "to": "2026-04-30"})).toBe(true);
  const c_ada_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ada", "amount": "10.35"}, p_ada));
  expect(await ui.editClaim(pg_uma, c_ada_0, {"amount": "1.00"})).toBe(true);
  expect(await ui.addProof(pg_uma, c_ada_0)).toBe(true);
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-09"})).toBe(true);
  expect(await ui.setApprover(pg_uma, p_ada, "wes")).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  await ui.refresh(pg_wes);
  expect(await ui.statement(pg_wes, p_cam)).toBe(true);
  expect(await ui.bulkGrade(pg_wes, [p_ben, p_cam], {"grade": "A", "from": "2026-03-01"})).toBe(2);
  expect(await ui.retire(pg_wes, p_ben, "2026-02-10")).toBe(true);
  const c_ada_1 = ui.must(await ui.addClaim(pg_wes, p_ada, {"amount": "10.25", "date": "2026-02-25", "ref": "R-1", "tags": " c "}));
  expect(await ui.editClaim(pg_wes, c_ada_0, {"amount": "0.04"})).toBe(true);
  expect(await ui.claimAction(pg_wes, c_ada_0, "open")).toBe(true);
  expect(await ui.addAlias(pg_wes, p_cam, "Al")).toBe(true);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ben)).toHaveCount(0);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(false);
  expect(await ui.addNote(pg_vic, "")).toBe(false);
  await ui.expectAuditView(pg_vic, "Cam", [
    `PERSON_ALIAS_ADDED sheet=${sheet} by=wes name=Cam alias=Al`,
    `PERSON_EDITED sheet=${sheet} by=wes name=Cam grade=A`,
    `STATEMENT sheet=${sheet} by=wes name=Cam due-total=0.00 claims=0`,
    `PERSON_HELD sheet=${sheet} by=uma name=Cam from=2026-03-09`,
    `POOL_MEMBER_ADDED sheet=${sheet} by=uma pool=P1 name=Cam share=33.33`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=A`
  ]);
  expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(false);
  expect(await ui.statement(pg_vic, p_ada)).toBe(false);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_ben)).toHaveCount(0);
  await ui.expectAudit(sheet, [
